using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search capability for the research agent.
/// Uses a simple HTML fetch approach; swap for a real search API in production.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _http;

    public WebSearchTool(HttpClient http) => _http = http;

    [Description("Searches the web for the given query and returns a list of result snippets. Use this to find information about a topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3,
        CancellationToken cancellationToken = default)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        // Simulated web search results — in production, wire up Bing Search API, Google Custom Search, or similar.
        var results = new List<object>();
        var encoded = WebUtility.UrlEncode(query);

        try
        {
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit={maxResults}&format=json";
            var response = await _http.GetStringAsync(url, cancellationToken);
            using var doc = JsonDocument.Parse(response);

            if (doc.RootElement.TryGetProperty("query", out var queryEl) &&
                queryEl.TryGetProperty("search", out var searchEl))
            {
                foreach (var item in searchEl.EnumerateArray())
                {
                    var title = item.GetProperty("title").GetString() ?? "";
                    var snippet = item.GetProperty("snippet").GetString() ?? "";
                    // Strip HTML tags from snippet
                    snippet = System.Text.RegularExpressions.Regex.Replace(snippet, "<.*?>", "");
                    results.Add(new { title, snippet, url = $"https://en.wikipedia.org/wiki/{WebUtility.UrlEncode(title)}" });
                }
            }
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Try a different query or check connectivity.";
        }

        if (results.Count == 0)
            return "No results found. Try rephrasing the query.";

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }

    [Description("Fetches the plain-text extract of a Wikipedia article. Use this to get detailed information about a specific topic found via search.")]
    public async Task<string> FetchArticleAsync(
        [Description("The exact Wikipedia article title")] string title,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(title);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&titles={encoded}&prop=extracts&exintro=true&explaintext=true&format=json";
            var response = await _http.GetStringAsync(url, cancellationToken);
            using var doc = JsonDocument.Parse(response);

            var pages = doc.RootElement.GetProperty("query").GetProperty("pages");
            foreach (var page in pages.EnumerateObject())
            {
                if (page.Value.TryGetProperty("extract", out var extract))
                {
                    var text = extract.GetString() ?? "No content found.";
                    // Truncate very long articles to stay within token budgets
                    return text.Length > 3000 ? text[..3000] + "\n\n[Truncated — use notes to record key points]" : text;
                }
            }

            return "Article not found. Check the title and try again.";
        }
        catch (HttpRequestException ex)
        {
            return $"Fetch failed: {ex.Message}";
        }
    }
}

using System.ComponentModel;
using System.Text;

namespace ResearchAgent;

/// <summary>
/// A note-taking tool that lets the agent record, list, and organize research findings.
/// </summary>
public sealed class NotesTool
{
    private readonly List<Note> _notes = [];

    public IReadOnlyList<Note> Notes => _notes;

    [Description("Saves a research note with a title and content. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The note content — key facts, quotes, or observations")] string content,
        [Description("Source URL or reference (optional)")] string? source = null)
    {
        var note = new Note(title, content, source, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Lists all saved research notes. Use this to review what you've found so far before writing a summary.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet. Use SaveNote to record findings.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var n = _notes[i];
            sb.AppendLine($"--- Note #{i + 1}: {n.Title} ---");
            sb.AppendLine(n.Content);
            if (!string.IsNullOrEmpty(n.Source))
                sb.AppendLine($"Source: {n.Source}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    [Description("Deletes a note by its 1-based index number.")]
    public string DeleteNote([Description("The 1-based index of the note to delete")] int index)
    {
        if (index < 1 || index > _notes.Count)
            return $"Invalid note index. Valid range: 1-{_notes.Count}";

        var removed = _notes[index - 1];
        _notes.RemoveAt(index - 1);
        return $"Deleted note: \"{removed.Title}\"";
    }
}

public sealed record Note(string Title, string Content, string? Source, DateTime CreatedUtc);

