+            return $"Search failed: {ex.Message}. Try a different query or check connectivity.";
+        }
+
+        if (results.Count == 0)
+            return "No results found. Try rephrasing the query.";
+
+        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
+    }
+
+    [Description("Fetches the plain-text extract of a Wikipedia article. Use this to get detailed information about a specific topic found via search.")]
+    public async Task<string> FetchArticleAsync(
+        [Description("The exact Wikipedia article title")] string title,
+        CancellationToken cancellationToken = default)
+    {
+        try
+        {
+            var encoded = WebUtility.UrlEncode(title);
+            var url = $"https://en.wikipedia.org/w/api.php?action=query&titles={encoded}&prop=extracts&exintro=true&explaintext=true&format=json";
+            var response = await _http.GetStringAsync(url, cancellationToken);
+            using var doc = JsonDocument.Parse(response);
+
+            var pages = doc.RootElement.GetProperty("query").GetProperty("pages");
+            foreach (var page in pages.EnumerateObject())
+            {
+                if (page.Value.TryGetProperty("extract", out var extract))
+                {
+                    var text = extract.GetString() ?? "No content found.";
+                    // Truncate very long articles to stay within token budgets
+                    return text.Length > 3000 ? text[..3000] + "\n\n[Truncated — use notes to record key points]" : text;
+                }
+            }
+
+            return "Article not found. Check the title and try again.";
+        }
+        catch (HttpRequestException ex)
+        {
+            return $"Fetch failed: {ex.Message}";
+        }
+    }
+}
