using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the host with DI ---
var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient<WebSearchTool>();
builder.Services.AddSingleton<NotesTool>();

// Register the chat client via MEAI abstraction
builder.Services.AddChatClient(cb => cb
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var host = builder.Build();

// --- Resolve services ---
var chatClient = host.Services.GetRequiredService<IChatClient>();
var searchTool = host.Services.GetRequiredService<WebSearchTool>();
var notesTool = host.Services.GetRequiredService<NotesTool>();

// --- Register tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(searchTool.SearchWebAsync),
    AIFunctionFactory.Create(searchTool.FetchArticleAsync),
    AIFunctionFactory.Create(notesTool.SaveNote),
    AIFunctionFactory.Create(notesTool.ListNotes),
    AIFunctionFactory.Create(notesTool.DeleteNote),
};

// --- Create the agent ---
var agent = new ChatClientAgent(chatClient,
    """
    You are a research assistant. Your job is to thoroughly research a topic the user provides.

    Follow this workflow:
    1. Search the web for the topic to find relevant articles.
    2. Fetch detailed content from the most promising results.
    3. Save key findings as notes — include titles, important facts, and source URLs.
    4. After gathering enough information (at least 3 quality sources), review your notes.
    5. Provide a well-structured summary with:
       - An overview paragraph
       - Key findings as bullet points
       - Sources cited at the end

    Be thorough but concise. Focus on factual, verifiable information.
    """,
    tools);

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍 AI Research Agent           ║");
Console.WriteLine("║  Enter a topic to research, or       ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        Console.WriteLine("Goodbye!");
        break;
    }

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching... (the agent will search, take notes, and summarize)");
    Console.ResetColor();
    Console.WriteLine();

    var chatHistory = new List<ChatMessage>
    {
        new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 15,
    };

    try
    {
        // Stream the agent's final response
        await foreach (var update in agent.InvokeStreamingAsync(chatHistory, options))
        {
            if (!string.IsNullOrEmpty(update.Text))
            {
                Console.Write(update.Text);
            }
        }

        Console.WriteLine();
        Console.WriteLine();

        // Show collected notes summary
        if (notesTool.Notes.Count > 0)
        {
            Console.ForegroundColor = ConsoleColor.DarkYellow;
            Console.WriteLine($"📝 {notesTool.Notes.Count} research note(s) saved during this session.");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

